ground_truth_sql:
SELECT "nct", "author", "year", "publication_type", "control_type", "cancer_type", "control_regimen", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Small Cell Lung' AND "control_type" = 'Chemo';

gt_sql_final:
SELECT "nct", "author", "year", "originial_publication_or_follow_up", "type_of_control", "cancer_type", "control_regimen", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Small Cell Lung' AND "type_of_control" = 'Chemo';
